package com.lexorion.payroll.api;import static com.lexorion.payroll.api.PayrollDtos.*;import com.lexorion.payroll.service.PayrollEmployeeService;import jakarta.validation.Valid;import java.net.URI;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/payroll/employees")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public class PayrollEmployeeController{private final PayrollEmployeeService service;public PayrollEmployeeController(PayrollEmployeeService s){service=s;}@GetMapping public List<PayrollEmployeeResponse> list(){return service.list();}@PostMapping public ResponseEntity<PayrollEmployeeResponse> create(@Valid@RequestBody CreatePayrollEmployee r){var v=service.create(r);return ResponseEntity.created(URI.create("/api/payroll/employees/"+v.employeeCode())).body(v);}@GetMapping("/{employeeCode}")public PayrollEmployeeResponse get(@PathVariable String employeeCode){return service.get(employeeCode);}@PatchMapping("/{employeeCode}")public PayrollEmployeeResponse update(@PathVariable String employeeCode,@Valid@RequestBody UpdatePayrollEmployee r){return service.update(employeeCode,r);}}
